import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';
import { Schema } from '../../schema';
import { normalizeStateTransition } from '../../stateValidation';
import { migrateLegacyState } from '../../stateMigration';

async function init() {
  await waitGlobalInitialized('Mvu');
  registerMvuSchema(Schema);
  eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, (variables, variablesBeforeUpdate) => {
    const previous = Schema.safeParse(migrateLegacyState(_.get(variablesBeforeUpdate, 'stat_data')));
    const candidate = Schema.safeParse(migrateLegacyState(_.get(variables, 'stat_data')));
    if (!previous.success || !candidate.success) {
      if (previous.success) {
        _.set(variables, 'stat_data', previous.data);
        console.warn('[苏北乡村] MVU更新未通过变量结构校验，已恢复更新前状态');
      } else {
        _.unset(variables, 'stat_data');
        console.error('[苏北乡村] 更新前状态与候选状态均不可验证，已拒绝非法候选值；请从最近有效楼层恢复');
        toastr.error('变量底表损坏，本次更新已拒绝，请使用设置中的变量恢复功能');
      }
      return;
    }
    try {
      _.set(variables, 'stat_data', normalizeStateTransition(previous.data, candidate.data));
    } catch (error) {
      _.set(variables, 'stat_data', previous.data);
      const message = error instanceof Error ? error.message : '状态转换校验失败';
      console.warn(`[苏北乡村] ${message}，已保留更新前状态`);
      toastr.warning(`${message}，本次变量更新已撤销`);
    }
  });
  console.info('[苏北乡村] MVU变量结构已注册');
}

$(() => {
  errorCatched(init)();
});
