import { klona } from 'klona';
import { Schema, type Schema as StatData } from './schema';
import { migrateLegacyState } from './stateMigration';

export type NormalizeStateTransitionOptions = {
  allowPromotionRequestIds?: readonly string[];
  allowShopRefreshRequest?: boolean;
  allowPlayerProfileEdit?: boolean;
  allowLocalInventoryTransaction?: boolean;
  allowSmsTransaction?: boolean;
  allowItemUseRequest?: boolean;
  allowSystemLifecycleUpdate?: boolean;
  allowLocalCharacterDelete?: boolean;
};

function validTimestamp(data: StatData['世界信息']['日期时间']): number | null {
  const { 年, 月, 日, 时, 分 } = data;
  if (年 <= 0 || 月 <= 0 || 日 <= 0) return null;
  const value = new Date(年, 月 - 1, 日, 时, 分);
  if (
    value.getFullYear() !== 年 ||
    value.getMonth() !== 月 - 1 ||
    value.getDate() !== 日 ||
    value.getHours() !== 时 ||
    value.getMinutes() !== 分
  ) {
    return null;
  }
  return value.getTime();
}

/**
 * 日期属于数值字段：把越界值纠正到合法公历范围，但不强制剧情每轮推进时间。
 * 年份仍为 0 时视为尚未初始化，允许月、日、时间分步生成。
 */
function normalizeWorldClock(previous: StatData, next: StatData): void {
  const clock = next.世界信息.日期时间;
  if (clock.年 <= 0) return;
  clock.月 = _.clamp(clock.月 || 1, 1, 12);
  const lastDay = new Date(clock.年, clock.月, 0).getDate();
  clock.日 = _.clamp(clock.日 || 1, 1, lastDay);
  clock.时 = _.clamp(clock.时, 0, 23);
  clock.分 = _.clamp(clock.分, 0, 59);

  // 世界时间倒退通常是模型算错；只恢复时钟，不撤销同批其他变量变化。
  const before = validTimestamp(previous.世界信息.日期时间);
  const after = validTimestamp(clock);
  if (before !== null && after !== null && after < before) {
    next.世界信息.日期时间 = klona(previous.世界信息.日期时间);
  }
}

function normalizePlayerNumbers(previous: StatData, next: StatData): void {
  const initializing = previous.世界信息.日期时间.年 === 0 && next.世界信息.日期时间.年 > 0;
  for (const skill of Object.keys(next.玩家信息.生活技能) as Array<keyof StatData['玩家信息']['生活技能']>) {
    // 技能等级本身由 Schema 限制为 0~3；非初始化阶段每轮最多成长 1 级。
    if (!initializing) {
      next.玩家信息.生活技能[skill] = Math.min(
        next.玩家信息.生活技能[skill],
        previous.玩家信息.生活技能[skill] + 1,
      );
    }
  }

  for (const [name, item] of Object.entries(next.玩家信息.物品栏)) {
    item.数量 = _.clamp(Math.floor(item.数量), 0, 9999);
    if (item.数量 <= 0) delete next.玩家信息.物品栏[name];
    if (!item.可使用) item.使用后消耗 = false;
  }
}

function normalizeAffection(previous: StatData, next: StatData): void {
  const beforeTimestamp = validTimestamp(previous.世界信息.日期时间);
  const afterTimestamp = validTimestamp(next.世界信息.日期时间);
  const crossedDay =
    beforeTimestamp !== null &&
    afterTimestamp !== null &&
    new Date(beforeTimestamp).toDateString() !== new Date(afterTimestamp).toDateString();
  const initializing = previous.世界信息.日期时间.年 === 0 && next.世界信息.日期时间.年 > 0;

  for (const [id, role] of Object.entries(next.角色信息)) {
    if (!role.最高阶段已解锁) role.对玩家的好感度 = Math.min(role.对玩家的好感度, 89);
    if (initializing) continue;
    if (crossedDay) {
      role.当日好感度提升 = 0;
      continue;
    }
    const before = previous.角色信息[id];
    if (!before) continue;
    const positiveDelta = Math.max(0, role.对玩家的好感度 - before.对玩家的好感度);
    role.当日好感度提升 = _.clamp(before.当日好感度提升 + positiveDelta, 0, 20);
  }
}

/**
 * 商店刷新是付费事务。模型若误碰前端请求标记，只回退商店子树；
 * 已有请求只有在完整生成 8 件有库存商品时才清除，失败时保留请求供下一轮重试。
 */
function normalizeShopTransaction(previous: StatData, next: StatData, options: NormalizeStateTransitionOptions): void {
  for (const product of Object.values(next.系统商店.商品)) {
    if (!product.可使用) product.使用后消耗 = false;
  }

  const beforePending = previous.系统商店.待刷新;
  const afterPending = next.系统商店.待刷新;
  const shelfChanged = !_.isEqual(previous.系统商店.商品, next.系统商店.商品);

  if (!beforePending && afterPending) {
    if (!options.allowShopRefreshRequest) {
      next.系统商店 = klona(previous.系统商店);
      return;
    }
    next.系统商店.商品 = klona(previous.系统商店.商品);
    next.玩家信息.人民币 = Math.max(0, Number((previous.玩家信息.人民币 - 100).toFixed(2)));
    return;
  }

  if (beforePending && !afterPending) {
    const products = Object.values(next.系统商店.商品);
    const completed = shelfChanged && products.length === 8 && products.every(product => product.库存 > 0);
    if (!completed) next.系统商店 = klona(previous.系统商店);
    return;
  }

  if (
    !beforePending &&
    !afterPending &&
    previous.世界信息.日期时间.年 > 0 &&
    shelfChanged &&
    !options.allowLocalInventoryTransaction
  ) {
    next.系统商店.商品 = klona(previous.系统商店.商品);
  }
}

/** 前端请求标记不能由模型伪造；只恢复标记本身，不影响同批剧情变量。 */
function normalizeItemUseRequest(previous: StatData, next: StatData, options: NormalizeStateTransitionOptions): void {
  const before = previous.玩家信息.待处理物品使用;
  const after = next.玩家信息.待处理物品使用;
  if (!before.物品名称 && after.物品名称 && !options.allowItemUseRequest) {
    next.玩家信息.待处理物品使用 = klona(before);
  }
}

/**
 * 普通角色升阶采用待升阶事务。错误或半成品只回退对应角色，不再撤销其它补丁。
 */
function normalizePromotionTransactions(
  previous: StatData,
  next: StatData,
  options: NormalizeStateTransitionOptions,
): void {
  const allowedRequestIds = new Set(options.allowPromotionRequestIds ?? []);

  for (const [id, role] of Object.entries(next.普通角色)) {
    const before = previous.普通角色[id];
    if (role.待升阶 && !before?.待升阶 && (!before || !allowedRequestIds.has(id))) {
      role.待升阶 = false;
    }
  }

  for (const [id, before] of Object.entries(previous.普通角色)) {
    const ordinary = next.普通角色[id];
    const promoted = next.角色信息[id];

    if (!before.待升阶 && promoted && !ordinary) {
      // 没有前端请求的直接升阶不落地；保留原普通角色等待玩家确认。
      delete next.角色信息[id];
      if (!options.allowLocalCharacterDelete) next.普通角色[id] = klona(before);
      continue;
    }

    if (!before.待升阶) continue;
    if (!ordinary && promoted) continue; // 原子升阶完成。
    if (!ordinary && !promoted) {
      if (!options.allowLocalCharacterDelete) next.普通角色[id] = klona(before);
      continue;
    }
    if (ordinary) ordinary.待升阶 = true;
  }
}

/**
 * 这里只实施数值计算与前端事务边界。人物档案、经历文本、剧情节奏等规则由世界书引导，
 * 不再因为某个文本字段不完整而抛错并撤销整批有效更新。
 */
export function normalizeStateTransition(
  previousInput: unknown,
  nextInput: unknown,
  options: NormalizeStateTransitionOptions = {},
): StatData {
  const previous = Schema.parse(migrateLegacyState(previousInput));
  const next = klona(Schema.parse(migrateLegacyState(nextInput)));

  if (!options.allowSystemLifecycleUpdate) next.系统状态 = klona(previous.系统状态);
  normalizeWorldClock(previous, next);
  normalizePlayerNumbers(previous, next);
  normalizeAffection(previous, next);
  normalizeShopTransaction(previous, next, options);
  normalizeItemUseRequest(previous, next, options);
  normalizePromotionTransactions(previous, next, options);

  if (previous.世界信息.日期时间.年 === 0 && next.世界信息.日期时间.年 > 0) {
    next.系统状态.初始化状态 = '完成';
    next.系统状态.初始化错误 = '';
  }
  return next;
}
